"""Business-day arithmetic for delivery estimates."""

from datetime import date, timedelta


def add_business_days(start: date, days: int, holidays: frozenset[date] = frozenset()) -> date:
    """The date ``days`` working days after ``start`` (Mon-Fri, skipping ``holidays``)."""
    if days < 0:
        raise ValueError("days must be zero or more")
    current = start
    while days:
        current += timedelta(days=1)
        if current.weekday() < 5 and current not in holidays:
            days -= 1
    return current
